solution:
def min_tokens(scores: list[int]) -> int:
    n = len(scores)
    tokens = [1] * n
    for i in range(1, n):                # more than a lower-scoring left neighbor
        if scores[i] > scores[i - 1]:
            tokens[i] = tokens[i - 1] + 1
    for i in range(n - 2, -1, -1):       # more than a lower-scoring right neighbor
        if scores[i] > scores[i + 1]:
            tokens[i] = max(tokens[i], tokens[i + 1] + 1)
    return sum(tokens)

perf.naive:
def min_tokens(scores: list[int]) -> int:
    n = len(scores)
    tokens = [1] * n
    changed = True
    while changed:                       # sweep again until no rule is broken
        changed = False
        for i in range(n):
            if i > 0 and scores[i] > scores[i - 1] and tokens[i] <= tokens[i - 1]:
                tokens[i] = tokens[i - 1] + 1
                changed = True
            if i < n - 1 and scores[i] > scores[i + 1] and tokens[i] <= tokens[i + 1]:
                tokens[i] = tokens[i + 1] + 1
                changed = True
    return sum(tokens)
